% Choose data source: 'generate', 'csv', 'mat', 'txt'
data_source = 'generate';  % Change as needed

switch data_source
    case 'generate'
        % Generate sample data
        Fs = 100e6;
        duration = 50e-6;
        t = 0:1/Fs:duration-1/Fs;
        f_center = 5e6;
        envelope = exp(-((t - duration/2).^2) / (2*(duration/10)^2));
        voltage_signal = envelope .* sin(2*pi*f_center*t);

    case 'csv'
        % Import from CSV file
        % Format expected: Column 1 = time (s), Column 2 = voltage (V)
