        % Import from MAT file
        filename = 'ultrasound_data.mat';
        load(filename);  % Expects variables: t, voltage_signal, Fs

    case 'txt'
        % Import from text file
        filename = 'ultrasound_data.txt';
        data = load(filename);
        t = data(:,1)';
        voltage_signal = data(:,2)';
