% Zero-padding for better frequency resolution (optional)
NFFT = 2^nextpow2(N) * 4;  % Zero-pad to 4x next power of 2

% Compute FFT
Y = fft(voltage_windowed, NFFT);

% Single-sided spectrum
P2 = abs(Y/N);
P1 = P2(1:NFFT/2+1);
P1(2:end-1) = 2*P1(2:end-1);

% Frequency vector
f = Fs*(0:(NFFT/2))/NFFT;
f_MHz = f / 1e6;

% Convert to dB
