idx_start_6dB = find(above_threshold, 1, 'first');
idx_end_6dB = find(above_threshold, 1, 'last');
bandwidth_6dB = f_MHz(idx_end_6dB) - f_MHz(idx_start_6dB);

% Find -20dB points
above_threshold_20 = magnitude_dB_normalized >= threshold_20dB;
idx_start_20dB = find(above_threshold_20, 1, 'first');
idx_end_20dB = find(above_threshold_20, 1, 'last');
bandwidth_20dB = f_MHz(idx_end_20dB) - f_MHz(idx_start_20dB);

%% ============== CREATE OUTPUT STRUCTURE ==============
results.time = t;
results.voltage = voltage_signal;
results.frequency_MHz = f_MHz;
results.magnitude_dB = magnitude_dB;
results.magnitude_dB_normalized = magnitude_dB_normalized;
results.sampling_frequency_MHz = Fs/1e6;
results.peak_frequency_MHz = f_MHz(peak_idx);
results.bandwidth_6dB_MHz = bandwidth_6dB;
results.bandwidth_20dB_MHz = bandwidth_20dB;

%% ============== PLOTTING ==============
figure('Position', [50, 50, 1400, 900], 'Color', 'w');

% Plot 1: Time domain
subplot(2,3,1);
plot(t*1e6, voltage_signal, 'b', 'LineWidth', 0.8);
xlabel('Time (\mus)', 'FontSize', 11);
ylabel('Voltage (V)', 'FontSize', 11);
title('Original Signal', 'FontSize', 12);
grid on;

% Plot 2: Windowed signal
subplot(2,3,2);
plot(t*1e6, voltage_windowed, 'b', 'LineWidth', 0.8);
xlabel('Time (\mus)', 'FontSize', 11);
ylabel('Voltage (V)', 'FontSize', 11);
title(['Windowed Signal (' window_type ')'], 'FontSize', 12);
grid on;

% Plot 3: Linear magnitude spectrum
subplot(2,3,3);
plot(f_MHz, P1*1000, 'r', 'LineWidth', 1);
xlabel('Frequency (MHz)', 'FontSize', 11);
ylabel('Magnitude (mV)', 'FontSize', 11);
title('Magnitude Spectrum (Linear)', 'FontSize', 12);
grid on;
xlim([0, Fs/2/1e6]);

% Plot 4: dB spectrum (full range)
subplot(2,3,4);
plot(f_MHz, magnitude_dB, 'Color', [0, 0.5, 0], 'LineWidth', 1);
xlabel('Frequency (MHz)', 'FontSize', 11);
ylabel('Magnitude (dB)', 'FontSize', 11);
title('Magnitude Spectrum (dB)', 'FontSize', 12);
grid on;
xlim([0, Fs/2/1e6]);

% Plot 5: Normalized dB spectrum with bandwidth markers
subplot(2,3,5);
plot(f_MHz, magnitude_dB_normalized, 'm', 'LineWidth', 1.2);
hold on;
yline(-6, '--r', '-6 dB', 'LineWidth', 1.5);
yline(-20, '--b', '-20 dB', 'LineWidth', 1.5);
xline(f_MHz(peak_idx), ':k', 'Peak', 'LineWidth', 1);

% Mark bandwidth region
if ~isempty(idx_start_6dB) && ~isempty(idx_end_6dB)
    fill([f_MHz(idx_start_6dB), f_MHz(idx_start_6dB:idx_end_6dB), f_MHz(idx_end_6dB)], ...
         [-60, magnitude_dB_normalized(idx_start_6dB:idx_end_6dB), -60], ...
         'r', 'FaceAlpha', 0.2, 'EdgeColor', 'none');
end

xlabel('Frequency (MHz)', 'FontSize', 11);
ylabel('Magnitude (dB) - Normalized', 'FontSize', 11);
title('Normalized Spectrum with Bandwidth', 'FontSize', 12);
grid on;
xlim([0, 20]);
ylim([-60, 5]);
legend('Spectrum', '-6dB', '-20dB', 'Peak', '-6dB BW', 'Location', 'northeast');

% Plot 6: Results summary
subplot(2,3,6);
axis off;
text_str = {
    '========== ANALYSIS RESULTS ==========';
    '';
    sprintf('Sampling Frequency: %.2f MHz', Fs/1e6);
    sprintf('Number of Samples: %d', N);
    sprintf('FFT Points: %d', NFFT);
    sprintf('Frequency Resolution: %.4f kHz', (f(2)-f(1))/1e3);
    '';
    sprintf('Peak Frequency: %.3f MHz', f_MHz(peak_idx));
    sprintf('Peak Magnitude: %.2f dB', magnitude_dB(peak_idx));
    '';
    sprintf('-6 dB Bandwidth: %.3f MHz', bandwidth_6dB);
    sprintf('-20 dB Bandwidth: %.3f MHz', bandwidth_20dB);
    sprintf('Fractional Bandwidth: %.1f%%', bandwidth_6dB/f_MHz(peak_idx)*100);
    '';
    sprintf('Window Function: %s', window_type);
    '======================================'
