output_data = [f_MHz', magnitude_dB', magnitude_dB_normalized'];
output_filename = 'frequency_spectrum_output.csv';
% writematrix(output_data, output_filename);  % Uncomment to save

% Display results in command window
fprintf('\n%s\n', text_str{:});
```

